func assertStringPath(t *testing.T, doc map[string]any, path, want string) {
	t.Helper()

	got, ok := lookupAnyPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	str, ok := got.(string)
	if !ok {
		t.Fatalf("%s = %T, want string", path, got)
	}
	if str != want {
